void mrb_gc_mark_context(mrb_state *mrb, struct mrb_context *c) {
  if (!c->stack) {
    return;
  }

  size_t n = (char *)c->stack_ptr - (char *)c->stack;
  n /= sizeof(mrb_value);

  for (size_t i = 0; i < n; i++) {
    mrb_value *val = &c->stack[i];
    if (!mrb_immediate_p(*val)) {
      mrb_gc_mark(mrb, *val);
    }
  }
}

void mrb_mark_context_stack(mrb_state *mrb, struct mrb_context *c)
{
  mrb_value *stack;
  mrb_value *sp;
  int i;

  if (c->stack == NULL) {
    return;
  }

  stack = c->stack;
  sp = c->sp;

  for (i = 0; i < sp - stack; i++) {
    if (!mrb_immediate_p(stack[i])) {
      mrb_gc_mark(mrb, &stack[i]);
    }
  }
}

void mrb_gc_mark_context_stack(mrb_state *mrb, struct mrb_context *c) {
  if (!c->stack) return;

  mrb_value *sp = c->stack + c->stack_size;
  mrb_value *base = c->stack;

  while (sp > base) {
    mrb_value *val = sp - 1;
    if (!mrb_immediate_p(*val)) {
      mrb_gc_mark(mrb, *val);
    }
    sp--;
  }
}

void mrb_gc_mark_context_stack(mrb_state *mrb, struct mrb_context *c) {
  if (!c->stack) return;
  int n = c->sp - c->stack;
  int i;
  for (i = 0; i < n; i++) {
    mrb_value *v = &c->stack[i];
    if (!mrb_immediate_p(*v)) {
