}

void mrb_gc_mark_context_stack(mrb_state *mrb, struct mrb_context *c) {
  if (!c->stack) return;

  mrb_value *sp = c->stack + c->stp;
  mrb_value *base = c->stack;
  mrb_value *p = base;

  while (p < sp) {
    if (!mrb_immediate_p(*p)) {
      mrb_gc_mark(mrb, *p);
    }
    p++;
  }
}
